def sort_list(lst):
    a = lst[:]
    for i in range(len(a)):
        max_i = i
        for j in range(i + 1, len(a)):
            if a[j] > a[max_i]:
                max_i = j
        a[i], a[max_i] = a[max_i], a[i]
    return a

def top_k(lst, k):
    a = sort_list(lst)
    return a[0:k]
